<?php
// Admin decision on one VietQR transfer. Expects $transfer (transaction_id, amount, reference); $decideBookingId returns to the booking page.
$transferId = (int)$transfer['transaction_id'];
$decideBookingId = $decideBookingId ?? null;
$transferDuplicate = ($transfer['payment_status'] ?? 'unpaid') !== 'unpaid';
?>
<form class="transfer-decide" method="post" action="<?= e(url('/admin/payments/transfers/'.$transferId)) ?>"><?= csrf_field() ?><?php if($decideBookingId): ?><input type="hidden" name="return_to" value="detail"><input type="hidden" name="booking_id" value="<?= (int)$decideBookingId ?>"><?php endif; ?>
<?php if($transferDuplicate): ?><p class="small text-danger mb-1"><?= e(__('Booking này đã được thanh toán. Nếu khoản chuyển này đã vào tài khoản thì đó là khoản trùng: ghi chú lý do, đóng giao dịch rồi hoàn lại cho khách.')) ?></p><?php endif; ?>
<label class="sr-only" for="transfer-note-<?= $transferId ?>"><?= e(__('Ghi chú giao dịch {reference}', ['reference'=>$transfer['reference']])) ?></label><textarea class="form-control form-control-sm mb-1" id="transfer-note-<?= $transferId ?>" name="note" maxlength="500" rows="2" placeholder="<?= e($transferDuplicate?__('Ghi chú lý do đóng giao dịch trùng (bắt buộc)'):__('Ghi chú (bắt buộc khi chưa nhận tiền)')) ?>"></textarea>
<div class="action-row"><?php if($transferDuplicate): ?><button class="btn btn-sm btn-outline-danger" type="submit" name="decision" value="reject" data-confirm="<?= e(__('Đóng giao dịch chuyển khoản trùng này? Trạng thái thanh toán của booking không đổi.')) ?>"><?= e(__('Đóng giao dịch trùng')) ?></button><?php else: ?><button class="btn btn-sm btn-primary" type="submit" name="decision" value="confirm" data-confirm="<?= e(__('Tài khoản đã nhận {amount}đ với nội dung {reference}?', ['amount'=>number_format((float)$transfer['amount'],0,',','.'), 'reference'=>$transfer['reference']])) ?>"><?= e(__('Đã nhận tiền')) ?></button><button class="btn btn-sm btn-outline-danger" type="submit" name="decision" value="reject" data-confirm="<?= e(__('Báo khách là chưa nhận được khoản chuyển này?')) ?>"><?= e(__('Chưa nhận được')) ?></button><?php endif; ?></div></form>
